    steps = [
        f"讀題定位：圈出「{tag}」並標記時間、地點、參與者、制度或史料類型。",
        f"整理證據：分開外來壓力、政府回應、地方行動與社會後果；本題核心是「{reason}」。",
        f"核對正解：選項 {aid}「{answer}」能同時回應題幹資料與晚清東西接觸衝突的歷史脈絡。",
        "排除誘答：檢查是否把個別條約或報告當成全部實況，或把改革、交流與衝突簡化為全有或全無。",
        "結論回查：確認分期、群體差異、制度層次與史料視角都已納入，沒有超出資料可支持的範圍。",
    ]
    return {"id": f"question-social-content-hist-ib-iv-1-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-hist-ib-iv-1"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫通商口岸、不平等條約、軍事科技、改革阻力、傳教教育、報刊公共討論、全球市場、民族敘事、移民城市與多重證據情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-hist-ib-iv-1", "examPatternRefs": refs, "solutionStrategy": "先建立晚清東西接觸的時間與制度背景，再比較戰爭、條約、技術、教育、報刊與地方社會的多重反應，最後用分期和跨來源證據檢驗單一敘事。", "solutionSteps": steps}

